{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Under Tennessee Code § 49-10-1403, parents would have to ensure their participating students take the state tests given to public school students in the same grade or course each year.",
      "rationale": "Conveys parental responsibility, annual testing, and the matching public-school grade or course. The summary separately states the alternate-assessment exemption."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Parents would also have to ensure that students in grade 11 take the examination given to public school students in that grade",
      "rationale": "Conveys the responsible actor, grade, and required public-school examination. The later exemption applies to these requirements."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Parents would also have to ensure that students in grade 11 take the examination given to public school students in that grade, and that students in kindergarten through grade 3 take three state-approved reading screeners each year during the department of education’s three testing windows.",
      "rationale": "Conveys parental responsibility, the K–3 scope, three approved annual screeners, and the department's three administration windows. The exemption is stated separately."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Test results would have to be reported to parents.",
      "rationale": "In context, this covers results from the tests required under the replacement subsection."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Students with disabilities whose individualized education program (IEP) says they would have taken an alternate assessment would be exempt from these requirements.",
      "rationale": "Identifies the exempt students, the IEP determination, and the exemption from the subsection's requirements."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "It would also require participating schools under two cited provisions to post lesson plans, syllabuses, academic standards, and a current list of library materials on their websites.",
      "rationale": "Conveys the publication duty and required categories, but does not specify that lesson plans, syllabuses, and standards must cover every class offered."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "Library materials would include course materials and content in various print, electronic, and other forms.",
      "rationale": "Includes curriculum materials and multiple formats, but does not convey the definition's reach to materials made available to students or its expressly enumerated categories, including applications, video games, and subscription content."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "All educators at those schools would have to hold a valid state-issued license to teach in a public school.",
      "rationale": "Conveys the all-educator licensing requirement, but replaces the specified state board of education as issuer with the broader description 'state-issued.'"
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "It would also require participating schools under two cited provisions to post lesson plans, syllabuses, academic standards, and a current list of library materials on their websites.",
      "rationale": "Covers the parallel publication requirement, but omits that the class-related documents must cover every class offered."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "Library materials would include course materials and content in various print, electronic, and other forms.",
      "rationale": "Partly conveys the parallel definitions, but omits their reach to materials made available to students and the expressly enumerated categories, including applications, video games, and subscription content."
    },
    {
      "proposition_id": "P11",
      "status": "partial",
      "summary_quote": "All educators at those schools would have to hold a valid state-issued license to teach in a public school.",
      "rationale": "Covers the parallel all-educator licensing duty, but does not identify the state board of education as the required issuing authority."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "The bill would make the same tests a condition of student participation under Tennessee Code § 49-6-2606(a)(1).",
      "rationale": "Expressly identifies the amended provision and participation condition, incorporating the previously described annual grade- or course-matched state tests."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "The bill would make the same tests a condition of student participation under Tennessee Code § 49-6-2606(a)(1).",
      "rationale": "Incorporates the previously described grade-eleven public-school examination and makes it a participation condition under the identified provision."
    },
    {
      "proposition_id": "P14",
      "status": "full",
      "summary_quote": "The bill would make the same tests a condition of student participation under Tennessee Code § 49-6-2606(a)(1).",
      "rationale": "Incorporates the previously described K–3 annual reading screeners and three department testing windows as a participation condition."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025.",
      "rationale": "States the effective date accurately."
    }
  ]
}
